module fsm_controller (
    input  wire       clk,
    input  wire       rst,
    input  wire       start_btn,
    input  wire       water_full,
    input  wire       lid_closed,
    output reg  [1:0] state,
    output reg        water_valve,
    output reg        motor_run,
    output reg        warning
);

    localparam S_IDLE  = 2'b00;
    localparam S_FILL  = 2'b01;
    localparam S_WASH  = 2'b10;
    localparam S_SPIN  = 2'b11;

    reg [3:0] timer;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state       <= S_IDLE;
            water_valve <= 1'b0;
            motor_run   <= 1'b0;
            warning     <= 1'b0;
            timer       <= 4'd0;
        end else begin
            case (state)
                S_IDLE: begin
                    water_valve <= 1'b0;
                    motor_run   <= 1'b0;
                    warning     <= 1'b0;
                    timer       <= 4'd0;
                    if (start_btn && lid_closed)
                        state <= S_FILL;
                end
                S_FILL: begin
                    water_valve <= 1'b1;
                    motor_run   <= 1'b0;
                    warning     <= 1'b0;
                    if (water_full) begin
                        water_valve <= 1'b0;
                        state       <= S_WASH;
                        timer       <= 4'd0;
                    end
                end
                S_WASH: begin
                    water_valve <= 1'b0;
                    if (!lid_closed) begin
                        motor_run <= 1'b0;
                        warning   <= 1'b1;
                    end else begin
                        motor_run <= 1'b1;
                        warning   <= 1'b0;
                        if (timer >= 4'd9) begin
                            state <= S_SPIN;
                            timer <= 4'd0;
                        end else begin
                            timer <= timer + 1'b1;
                        end
                    end
                end
                S_SPIN: begin
                    water_valve <= 1'b0;
                    if (!lid_closed) begin
                        motor_run <= 1'b0;
                        warning   <= 1'b1;
                    end else begin
                        motor_run <= 1'b1;
                        warning   <= 1'b0;
                        if (timer >= 4'd4) begin
                            state <= S_IDLE;
                            timer <= 4'd0;
                        end else begin
                            timer <= timer + 1'b1;
                        end
                    end
                end
                default: state <= S_IDLE;
            endcase
        end
    end

endmodule
